-- GENERATED by scripts/gen_manual_seed.mjs from the approved Roadie Manual. Status needs_review: Moose publishes.

INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch1-1', 1, 1, 'WELCOME TO THE CREW', 'needs_review', '<p>Congratulations. You made it backstage.</p>
<p>Whether you’re behind the decks, working the crowd, or keeping this beautiful madhouse running, you’re part of the Sanctuary Rocks crew.</p>
<p>Around here, we take our music seriously. Ourselves? Not so much.</p>
<h3 class="subhead">What We’re All About</h3>
<p class="listline">✦ Good music: rock, metal, and the sounds that bring our community together.</p>
<p class="listline">✦ Great people: regulars and first-time guests both deserve a welcome.</p>
<p class="listline">✦ Teamwork: nobody should have to carry the show alone.</p>
<p class="listline">✦ Fun without the drama: this is a rock club, not a reality television audition.</p>
<h3 class="subhead">Your Backstage Pass</h3>
<p>This guide explains roles, scheduling, club expectations, and what to do when the unexpected happens. No unnecessary lectures. No complicated instructions.</p>
<p>BOTTOM LINE: Ask when you’re unsure; guessing makes extra work for everyone.</p>
<h3 class="subhead">One Last Thing</h3>
<p>Show up when you’ve committed to a shift, communicate when things change, and treat people with respect.</p>
<p>The music brings them in. The people make them stay.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch1-1';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch2-1', 2, 1, 'THE CREW CODE', 'needs_review', '<p>Because even rock stars need a little structure.</p>
<p>Sanctuary Rocks should be fun. A reliable crew keeps it that way.</p>
<h3 class="subhead">1. Show Up for Your Gig</h3>
<p>Real life happens. Computers crash. The internet decides to take a vacation.</p>
<p class="listline">✦ Know your shift.</p>
<p class="listline">✦ Give early notice if you can’t make it.</p>
<p class="listline">✦ Help the crew arrange coverage when practical.</p>
<p>BOTTOM LINE: If you can’t make the show, give us a heads-up.</p>
<h3 class="subhead">2. Leave the Drama Offstage</h3>
<p>Disagreements happen; public arguments don’t help.</p>
<p class="listline">✦ Handle routine conflicts respectfully and privately when safe.</p>
<p class="listline">✦ Take serious or unresolved concerns to management.</p>
<p>BOTTOM LINE: Bring the energy, not the unnecessary drama.</p>
<h3 class="subhead">3. Respect the Crew</h3>
<p class="listline">✦ DJs, hosts, managers, and support staff all matter.</p>
<p class="listline">✦ Communicate respectfully and help each other when possible.</p>
<p>BOTTOM LINE: One crew. No backstage power trips.</p>
<h3 class="subhead">4. Make Guests Feel Welcome</h3>
<p class="listline">✦ Greet newcomers when possible.</p>
<p class="listline">✦ Include people without pressuring them to participate.</p>
<p class="listline">✦ Respect those who just want to listen.</p>
<p>BOTTOM LINE: The people make them stay.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch2-1';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch2-2', 2, 2, 'THE CREW CODE · Continued', 'needs_review', '<h3 class="subhead">5. Know Your Role</h3>
<p class="listline">✦ Take responsibility for your own tasks.</p>
<p class="listline">✦ Ask when you’re unsure.</p>
<p class="listline">✦ Share ideas that might improve SR.</p>
<p>BOTTOM LINE: Own your gig, support the crew.</p>
<h3 class="subhead">6. Represent SR Proudly</h3>
<p class="listline">✦ Enjoy yourself and be yourself.</p>
<p class="listline">✦ Treat guests and teammates respectfully.</p>
<p class="listline">✦ Follow approved club guidelines.</p>
<p>BOTTOM LINE: Be the reason someone comes back.</p>
<h3 class="subhead">The Unwritten Rule</h3>
<p>Don’t make Moose regret giving us the keys to the asylum. Kidding. Mostly.</p>
<p>Nobody expects perfection. We expect communication, teamwork, and a genuine effort.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch2-2';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch3-1', 3, 1, 'THE SETLIST', 'needs_review', '<p>Showtime, schedules, and the occasional plot twist.</p>
<p>Every great show needs a lineup. The official SR schedule is the source of truth for upcoming sets and assignments.</p>
<h3 class="subhead">1. Know When You’re On</h3>
<p class="listline">✦ Check the schedule regularly, especially before your shift.</p>
<p class="listline">✦ Treat an accepted shift as a commitment.</p>
<p>BOTTOM LINE: If you’re on the schedule, we’re counting on you.</p>
<h3 class="subhead">2. When Real Life Crashes the Party</h3>
<p>Second Life isn’t First Life. Family, work, and technology sometimes win.</p>
<p class="listline">✦ Notify the designated scheduling contact as soon as possible.</p>
<p class="listline">✦ Post in the designated Discord coverage channel.</p>
<p class="listline">✦ Say whether you’ll be late or absent; personal details aren’t necessary.</p>
<p class="listline">✦ Help find coverage if you reasonably can.</p>
<p>BOTTOM LINE: Calling out isn’t the problem. Leaving everyone guessing is.</p>
<h3 class="subhead">3. Trading Places</h3>
<p class="listline">✦ Both staff members agree to a swap.</p>
<p class="listline">✦ Request approval from the scheduling contact.</p>
<p class="listline">✦ Make sure the official schedule is updated.</p>
<p>BOTTOM LINE: Swap the shift, not the confusion.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch3-1';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch3-2', 3, 2, 'THE SETLIST · Continued', 'needs_review', '<h3 class="subhead">4. Be Ready for Showtime</h3>
<p class="listline">✦ DJs: check software, music, and connection before the set.</p>
<p class="listline">✦ Hosts: be ready to welcome guests and support the DJ.</p>
<p class="listline">✦ Report technical difficulties promptly.</p>
<p>BOTTOM LINE: A little preparation saves a lot of chaos.</p>
<h3 class="subhead">5. The Handoff</h3>
<p class="listline">✦ Outgoing and incoming DJs coordinate the shared stream handoff.</p>
<p class="listline">✦ Hosts pass along any useful information to the next shift.</p>
<p>BOTTOM LINE: The show shouldn’t stop because the lineup changes.</p>
<h3 class="subhead">6. Picking Up an Open Set</h3>
<p class="listline">✦ Volunteer through the coverage channel or scheduler.</p>
<p class="listline">✦ Wait for confirmation before assuming the shift is yours.</p>
<p class="listline">✦ Nobody is expected to be available around the clock.</p>
<p>BOTTOM LINE: Helping is appreciated. Burning out isn’t.</p>
<h3 class="subhead">7. When Nobody Shows Up</h3>
<p class="listline">✦ Check whether a delay was reported.</p>
<p class="listline">✦ Notify scheduling and follow confirmed coverage instructions.</p>
<p class="listline">✦ Don’t promise a replacement before one is confirmed.</p>
<p>BOTTOM LINE: No missing-person posters required.</p>
<h3 class="subhead">The Setlist Survival Rule</h3>
<p>Be dependable, communicate early, and don’t leave your crew hanging.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch3-2';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch4-1', 4, 1, 'KNOW YOUR GIG', 'needs_review', '<p>Different roles. One crew. One hell of a show.</p>
<p>Nobody needs to do everything. Everybody needs to know their part.</p>
<h3 class="subhead">1. DJs — The Sound Behind the Sanctuary</h3>
<p class="listline">✦ Arrive prepared and check broadcasting equipment.</p>
<p class="listline">✦ Log into the SR DJ board at the start of your set.</p>
<p class="listline">✦ Coordinate a smooth stream handoff with the outgoing DJ.</p>
<p class="listline">✦ Communicate with your host and acknowledge the crowd.</p>
<p class="listline">✦ Follow approved SR music and broadcasting guidelines.</p>
<p class="listline">✦ Log out of the DJ board when finished.</p>
<p>BOTTOM LINE: The shared music stream continues independently of DJ board logout; logout does not automatically switch the stream to radio.</p>
<h3 class="subhead">2. Hosts — The Heart of the Party</h3>
<p class="listline">✦ Arrive prepared and log into the Host Board.</p>
<p class="listline">✦ Welcome guests and support the DJ.</p>
<p class="listline">✦ Keep local chat lively and inclusive without spamming.</p>
<p class="listline">✦ Share relevant announcements.</p>
<p class="listline">✦ Refer unresolved issues to management.</p>
<p class="listline">✦ Log out at the end of your shift.</p>
<p>BOTTOM LINE: Make guests feel like they belong.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch4-1';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch4-2', 4, 2, 'KNOW YOUR GIG · Continued', 'needs_review', '<h3 class="subhead">3. Management — Keeping the Wheels Turning</h3>
<p class="listline">✦ Keep schedules and coverage organized.</p>
<p class="listline">✦ Help resolve routine problems and communicate updates.</p>
<p class="listline">✦ Handle complaints fairly and privately.</p>
<p class="listline">✦ Recognize staff contributions.</p>
<p class="listline">✦ Take decisions outside delegated authority to Moose.</p>
<p>BOTTOM LINE: Support the crew; don’t micromanage the show.</p>
<h3 class="subhead">4. Working Together</h3>
<p class="listline">✦ DJs should not have to handle every guest interaction.</p>
<p class="listline">✦ Hosts should not be expected to fix every technical problem.</p>
<p class="listline">✦ Moose should not have to resolve every little issue.</p>
<p>BOTTOM LINE: Help where you can, but don’t carry the club alone.</p>
<h3 class="subhead">5. When You’re Off the Clock</h3>
<p class="listline">✦ Enjoy the club as a visitor when not scheduled.</p>
<p class="listline">✦ Offer help voluntarily, never out of pressure.</p>
<p>BOTTOM LINE: Even rock stars deserve downtime.</p>
<h3 class="subhead">The Backstage Bottom Line</h3>
<p>Know your gig. Respect the crew. Keep the music alive.</p>
<p>We’re running a rock club, not launching a spaceship.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch4-2';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch5-1', 5, 1, 'WHEN THINGS GO SIDEWAYS', 'needs_review', '<p>Technical meltdowns, missing rock stars, and other backstage disasters.</p>
<p>Streams crash. Computers freeze. People get their wires crossed. Most problems need communication and common sense, not an emergency meeting.</p>
<h3 class="subhead">1. When the Music Dies</h3>
<p class="listline">✦ DJ: check broadcasting software, internet, and the SR stream connection.</p>
<p class="listline">✦ DJ: tell the host and technical contact if the issue continues.</p>
<p class="listline">✦ Host: give guests a brief update and keep things friendly.</p>
<p class="listline">✦ Do not change or disconnect the shared stream without coordination.</p>
<p>BOTTOM LINE: Stay calm. Check the connection. Keep people informed.</p>
<h3 class="subhead">2. The Missing DJ or Host</h3>
<p class="listline">✦ Check for a reported delay.</p>
<p class="listline">✦ Contact the missing person once if appropriate.</p>
<p class="listline">✦ Notify scheduling or coverage management.</p>
<p class="listline">✦ Don’t promise a replacement until confirmed.</p>
<p>BOTTOM LINE: Check, communicate, coordinate.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch5-1';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch5-2', 5, 2, 'WHEN THINGS GO SIDEWAYS · Continued', 'needs_review', '<h3 class="subhead">3. When Personalities Collide</h3>
<p class="listline">✦ Keep ordinary disagreements respectful and out of public chat.</p>
<p class="listline">✦ Avoid gossip and taking sides.</p>
<p class="listline">✦ Take serious or unresolved concerns to management.</p>
<p class="listline">✦ For harassment, threats, or safety concerns, don’t require private confrontation; seek management help and use SL reporting tools if appropriate.</p>
<p>BOTTOM LINE: Handle the problem, not the audience.</p>
<h3 class="subhead">4. Guests Forget Their Manners</h3>
<p class="listline">✦ Do not escalate arguments.</p>
<p class="listline">✦ Remind guests of expectations when appropriate.</p>
<p class="listline">✦ Ask authorized management to address continued disruptions.</p>
<p class="listline">✦ Only authorized staff should issue bans or removals under policy.</p>
<p>BOTTOM LINE: Everyone can rock; nobody gets a free pass to ruin the show.</p>
<h3 class="subhead">5. When Equipment Gets Possessed</h3>
<p class="listline">✦ Identify the affected board or device.</p>
<p class="listline">✦ Record errors and take a screenshot if useful.</p>
<p class="listline">✦ Tell the designated technical contact.</p>
<p class="listline">✦ Don’t reset or modify equipment without authorization.</p>
<p>BOTTOM LINE: Report the gremlins. Don’t feed them.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch5-2';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch5-3', 5, 3, 'WHEN THINGS GO SIDEWAYS · Continued', 'needs_review', '<h3 class="subhead">6. When You Need Management</h3>
<p class="listline">✦ Escalate unresolved coverage, conduct, or technical problems.</p>
<p class="listline">✦ Send major policy, discipline, and security decisions to authorized senior management or Moose.</p>
<p class="listline">✦ Keep reports factual and concise.</p>
<p>BOTTOM LINE: Give Moose fewer headaches, not more mysteries.</p>
<h3 class="subhead">7. Everything at Once</h3>
<p class="listline">✦ Address safety concerns first.</p>
<p class="listline">✦ Identify the most urgent operational issue.</p>
<p class="listline">✦ Contact the right person.</p>
<p class="listline">✦ Afterward, document what still needs fixing.</p>
<p>BOTTOM LINE: Even chaos needs a queue.</p>
<h3 class="subhead">The Backstage Survival Rule</h3>
<p>Don’t panic. Don’t escalate. Don’t assume somebody else handled it.</p>
<p>If everything catches metaphorical fire, report it before roasting marshmallows.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch5-3';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch6-1', 6, 1, 'KEEPING THE ROCK ALIVE', 'needs_review', '<p>The music brings them in. The people make them stay.</p>
<p>SR is more than a building filled with dancing avatars and loud music. People can hear music anywhere in Second Life. We want them to choose Sanctuary Rocks.</p>
<h3 class="subhead">1. Make Guests Part of the Show</h3>
<p class="listline">✦ Greet new arrivals when possible.</p>
<p class="listline">✦ Include people without putting them on the spot.</p>
<p class="listline">✦ Recognize regulars without ignoring newcomers.</p>
<p class="listline">✦ Respect guests who just want the music.</p>
<p>BOTTOM LINE: Make people welcome, not obligated.</p>
<h3 class="subhead">2. Bring Your Personality</h3>
<p class="listline">✦ Enjoy your announcements and show enthusiasm.</p>
<p class="listline">✦ Find your own style as a DJ or host.</p>
<p class="listline">✦ Keep jokes inclusive rather than at somebody’s expense.</p>
<p>BOTTOM LINE: Personality makes the party.</p>
<h3 class="subhead">3. Keep Things Interesting</h3>
<p class="listline">✦ Suggest themes, trivia, celebrations, and community activities.</p>
<p class="listline">✦ Bring ideas to the right event contact.</p>
<p class="listline">✦ Accept that not every idea can go ahead.</p>
<p>BOTTOM LINE: Even the upside-down dancer might have a great idea.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch6-1';
INSERT INTO policies(slug, chapter, ord, title, status, draft_html, updated_at) VALUES ('ch6-2', 6, 2, 'KEEPING THE ROCK ALIVE · Continued', 'needs_review', '<h3 class="subhead">4. Support Fellow Rock Stars</h3>
<p class="listline">✦ Recognize great sets, welcoming hosts, and helpful crew.</p>
<p class="listline">✦ Celebrate without turning appreciation into a popularity contest.</p>
<p class="listline">✦ Respect everyone’s time and boundaries.</p>
<p>BOTTOM LINE: Build each other up.</p>
<h3 class="subhead">5. Help SR Grow Naturally</h3>
<p class="listline">✦ Share upcoming events appropriately.</p>
<p class="listline">✦ Invite interested friends and visitors.</p>
<p class="listline">✦ Listen to feedback and pass useful suggestions along.</p>
<p>BOTTOM LINE: Give people a reason to return, not a sales pitch.</p>
<h3 class="subhead">6. Remember Why We’re Here</h3>
<p class="listline">✦ Communicate when things become overwhelming.</p>
<p class="listline">✦ Take breaks when needed.</p>
<p class="listline">✦ Keep the atmosphere enjoyable for guests and staff.</p>
<p>BOTTOM LINE: Take music seriously. Take care of people. Have fun.</p>
<h3 class="subhead">The Final Encore</h3>
<p>Every DJ, host, manager, and guest helps make SR what it is.</p>
<p>The music brings them in. The people make them stay.</p>', 1793404800000);
INSERT INTO policy_versions(policy_id, title, html, kind, at) SELECT id, title, draft_html, 'imported', 1793404800000 FROM policies WHERE slug = 'ch6-2';

